  "The session must end after it starts": "Jam berakhir harus setelah jam mulai",
  "Enter the session start and end or the approximate position": "Isi waktu mulai dan berakhir atau koordinat pendekatan",
  "Enter at least one point with easting and northing": "Isi minimal satu titik dengan easting dan northing",
  "Backsight reference easting": "Easting titik ikat belakang",
  "Backsight reference northing": "Northing titik ikat belakang",
  "Start station easting": "Easting titik awal",
