  "ABP = Σ quantity × days × unit cost; lines from the price list take the unit cost (HPJ) of the rate build-up.": "ABP = Σ jumlah × hari × biaya satuan; baris dari daftar tarif memakai HPJ dari rincian tarifnya.",
  "Risk premium and margin are percentages of the ABP; bid price = ABP + risk premium + margin, rounded up.": "Premi risiko dan marjin dihitung sebagai persentase dari ABP; harga penawaran = ABP + premi risiko + marjin, dibulatkan ke atas.",
  "Minimum client price = lines from the price list at their minimum selling price, other lines at cost.": "Harga minimum klien = baris dari daftar tarif pada harga jual minimumnya, baris lain pada nilai biayanya.",
  "Difficulty index = weighted average of the factor scores, rounded half up; the region zone scores itself.": "Indeks kesulitan = rata-rata tertimbang nilai faktor, dibulatkan (0,5 ke atas); zona wilayah dinilai otomatis.",
