  "Empty tables use the company defaults shown on this page, to be confirmed by the pricing committee. Fill them in to change them.": "Tabel yang kosong memakai nilai bawaan perusahaan seperti tercantum di halaman ini, menunggu penetapan komite penawaran harga. Isi tabelnya bila ingin mengubah.",
