  "Project difficulty factors, risk premium by difficulty index, margin, maximum cost ratio, approval authority and receivables rules.": "Faktor indeks kesulitan proyek, premi risiko menurut indeks, marjin, rasio biaya maksimum, kewenangan pemutus, dan ketentuan penagihan piutang.",
